package com.provex.app.domain.model

/**
 * Compact opportunity recommendation card generated by the Career Opportunity Assistant.
 * Explicitly identifies whether a recommendation is an illustrative role archetype
 * or a verified live listing from a backend source.
 */
data class AssistantOpportunityCard(
    val id: String,
    val roleTitle: String,
    val category: String, // e.g. "Internship", "Entry-Level", "Junior Developer"
    val workMode: String? = null,
    val location: String? = null,
    val relevantSkills: List<String>,
    val relevanceExplanation: String,
    val sourceLabel: String = "PROVEX Role Archetype",
    val isLiveVacancy: Boolean = false,
    val sampleJobDescription: String? = null,
)

/**
 * Personalized guidance generated by the career opportunity engine based on the user's role query
 * and their existing Career Profile.
 */
data class AssistantPersonalizedGuidance(
    val roleQuery: String,
    val summary: String,
    val suitableRoles: List<String>,
    val commonlyRequestedSkills: List<String>,
    val matchedProfileSkills: List<String>, // Self-reported skills that match
    val skillsToStrengthen: List<String>,   // Commonly requested skills missing from profile
    val projectIdeas: List<String>,
    val preparationChecklist: List<String>,
    val opportunityCards: List<AssistantOpportunityCard>,
    val searchOptionsExplanation: String,
    val profileMissingPrompt: String? = null,
)

/**
 * Represents a chat message in the Career Opportunity Assistant conversation.
 */
data class AssistantChatMessage(
    val id: String,
    val isUser: Boolean,
    val text: String,
    val timestamp: Long = System.currentTimeMillis(),
    val guidance: AssistantPersonalizedGuidance? = null,
    val isLoading: Boolean = false,
)
